<script setup lang="ts">
import { useApi, isCancelled } from "./lib/api";
const api = useApi();
import { computed, onMounted, onUnmounted, ref, watch } from 'vue';
import { Activity, ArrowUpRight, CalendarDays, CheckCircle2, Clock3, Database, Download, Globe2, RadioTower, RefreshCw, Server, ShieldCheck, TriangleAlert, Users, Zap } from 'lucide-vue-next';
import { t, locale } from './i18n';
import CountryMark from './CountryMark.vue';
type User={id:number;username:string;enabled:boolean;expires:number;quota:number;upload:number;download:number;vless_traffic:number;hy2_traffic:number};
type Node={id:string;name:string;protocol:string;enabled:boolean;managed_by?:string;probe_ip:string;probe_error:string;country:string;country_code:string};
type Resource={id:string;pool_group?:string;enabled:boolean;reachable:boolean;source_stale?:boolean;node_ids:string[]};
type DashboardState={runtime?:{mode:'normal'|'no_logs';audit_enabled:boolean;traffic_history_enabled:boolean};me:{role:string};users:User[];nodes:Node[];ip_pool:Resource[];totals:{upload:number;download:number;active:number};unread_messages:number;system:{status:string;uptime:number;heap:number;cert_expires:number;services?:{name:string;active:boolean}[]};audit:{at:number;actor:string;action:string;target:string}[]};
type Bucket={at:number;upload:number;download:number};
type Data={generated_at:number;traffic:{range:string;start:number;end:number;bucket_seconds:number;upload:number;download:number;today:number;previous:number;comparison_available:boolean;first_record:number;buckets:Bucket[];leaders:{user_id:number;username:string;upload:number;download:number}[]};subscriptions?:{total:number;enabled:number;queued:number;failed:number;stale_resources:number;next_at:number};public?:{enabled:boolean;running:boolean;phase:string;max_resources:number;checked:number;discovered:number;skipped:number;blacklist:number;added:number;removed:number;finished_at:number;next_at:number;error:string;sources:{id:string;queued:boolean;running:boolean;error:string;last_success:number}[]}};
const props=defineProps<{state:DashboardState;simple?:boolean}>();
const emit=defineEmits<{navigate:[page:string];refresh:[]}>();
const owner=computed(()=>props.state.me.role==='owner');
const noLogs=computed(()=>props.state.runtime?.traffic_history_enabled===false||props.state.runtime?.mode==='no_logs');
const period=ref('24h'),data=ref<Data|null>(null),loading=ref(false),error=ref(''),showDown=ref(true),showUp=ref(true),activePoint=ref<number|null>(null);
const bytes=(n=0)=>{if(n<1024)return Math.round(n)+' B';const p=Math.min(4,Math.floor(Math.log(n)/Math.log(1024)));return (n/1024**p).toFixed(p>1?2:0)+' '+['B','KB','MB','GB','TB'][p]};
const date=(at=0)=>at?new Date(at*1000).toLocaleString(locale.value,{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}):t('尚未执行');
const pointDate=(at:number)=>new Date(at*1000).toLocaleString(locale.value,period.value==='24h'?{month:'2-digit',day:'2-digit',hour:'2-digit'}:{month:'2-digit',day:'2-digit'});
const periods=computed(()=>[{id:'24h',label:t('24 小时')},{id:'7d',label:t('7 天')},{id:'30d',label:t('30 天')}]);
const total=computed(()=>(data.value?.traffic.upload||0)+(data.value?.traffic.download||0));
const selectedLabel=computed(()=>periods.value.find(x=>x.id===period.value)?.label);
const comparison=computed(()=>{if(noLogs.value)return t('停止新增记录，不代表当前用量');const v=data.value?.traffic;if(!v?.comparison_available)return t('历史不足，暂不比较');if(!v.previous)return t('上个区间无流量');const p=(total.value-v.previous)/v.previous*100;return (p>=0?'+':'')+p.toFixed(1)+'% · '+t('较上个区间')});
const ordinary=computed(()=>props.state.nodes.filter(n=>!n.managed_by));
const publicNodes=computed(()=>props.state.nodes.filter(n=>n.managed_by));
const privateIPs=computed(()=>props.state.ip_pool.filter(p=>p.pool_group!=='public'));
const publicIPs=computed(()=>props.state.ip_pool.filter(p=>p.pool_group==='public'));
const healthy=computed(()=>privateIPs.value.filter(p=>p.enabled&&p.reachable).length);
const expiring=computed(()=>props.state.users.filter(u=>u.enabled&&u.expires>Date.now()/1000&&u.expires<Date.now()/1000+7*86400).length);
const exhausted=computed(()=>props.state.users.filter(u=>u.enabled&&u.quota>0&&u.upload+u.download>=u.quota).length);
const certDays=computed(()=>Math.max(0,Math.floor((props.state.system.cert_expires-Date.now()/1000)/86400)));
const protocolTotals=computed(()=>[{name:'VLESS',value:props.state.users.reduce((s,u)=>s+u.vless_traffic,0),color:'#6d8cf5'},{name:'Hysteria2',value:props.state.users.reduce((s,u)=>s+u.hy2_traffic,0),color:'#14b8a6'}]);
const protocolTotal=computed(()=>protocolTotals.value.reduce((s,p)=>s+p.value,0));
const exits=computed(()=>{const m=new Map<string,Node>();for(const n of (props.simple?ordinary.value:props.state.nodes))if(n.enabled&&n.probe_ip)m.set(n.probe_ip,n);return [...m.values()].slice(0,6)});
const attention=computed(()=>[
 {count:props.state.system.status==='applied'?0:1,label:t('配置等待同步'),page:'system'},
 {count:privateIPs.value.filter(p=>p.enabled&&!p.reachable).length,label:t('私有出口待检测或异常'),page:'ips'},
 {count:data.value?.subscriptions?.stale_resources||0,label:t('旧订阅资源需要处理'),page:'ips'},
 {count:data.value?.subscriptions?.failed||0,label:t('订阅来源更新失败'),page:'sources'},
 {count:data.value?.public?.sources.filter(s=>!!s.error).length||0,label:t('公共来源抓取异常'),page:'public/sources'},
 {count:expiring.value,label:t('成员即将在 7 天内到期'),page:'users'},
 {count:exhausted.value,label:t('成员流量额度已用尽'),page:'users'},
 {count:props.state.system.cert_expires&&certDays.value<14?1:0,label:t('证书将在 14 天内到期'),page:'system'},
].filter(v=>v.count>0&&(!props.simple||!['system','public/sources'].includes(v.page))));
const buckets=computed(()=>data.value?.traffic.buckets||[]);
const maxValue=computed(()=>Math.max(1,...buckets.value.map(b=>Math.max(showDown.value?b.download:0,showUp.value?b.upload:0)))*1.15);
const path=(key:'upload'|'download')=>buckets.value.map((b,i)=>(i?'L':'M')+(i*720/Math.max(1,buckets.value.length-1)).toFixed(2)+','+(178-b[key]/maxValue.value*156).toFixed(2)).join(' ');
const area=(key:'upload'|'download')=>path(key)+' L720,180 L0,180 Z';
const inspected=computed(()=>activePoint.value===null?null:buckets.value[activePoint.value]);
const labels=computed(()=>[0,.25,.5,.75,1].map(p=>buckets.value[Math.round(p*(buckets.value.length-1))]?.at).filter((v):v is number=>v!==undefined));
const auditName=(action:string)=>t(({initialize:'初始化',fetch_public_sources:'抓取公共来源',public_pool_cycle:'公共代理筛选',public_pool_settings:'公共采集策略',save_ip:'保存 IP 资源',delete_ip:'删除 IP 资源',save_node:'应用节点',delete_node:'删除节点',create_user:'创建成员',delete_user:'删除成员','refresh-import-source':'订阅来源自动更新','create-import-source':'添加订阅来源','delete-import-source':'删除订阅来源','update-settings':'更新系统设置',quality_test:'IP 质量检测',speed_test:'出口测速','send-message':'发送站内信'} as Record<string,string>)[action]|| (action.startsWith('update_user')?'更新成员':action));
let controller:AbortController|undefined,timer:ReturnType<typeof setInterval>|undefined,sequence=0;
async function load(){const seq=++sequence;controller?.abort();controller=new AbortController();loading.value=true;error.value='';try{const value=await api<Data>('/dashboard?range='+period.value+'&tz='+(-new Date().getTimezoneOffset()),'GET',undefined,{signal:controller.signal});if(seq===sequence)data.value=value;}catch(e){if(seq===sequence&&!isCancelled(e))error.value=(e as Error).message}finally{if(seq===sequence)loading.value=false}}
watch(period,()=>{activePoint.value=null;load()});
onMounted(()=>{load();timer=setInterval(()=>{if(!document.hidden&&!loading.value)load()},30000)});
onUnmounted(()=>{sequence++;controller?.abort();clearInterval(timer)});
</script>

<template>
<section :class="['business-dashboard',{'dashboard-simple':simple}]">
 <header class="dash-heading"><div><span class="dash-eyebrow">{{t('运营工作台')}}</span><h2>{{t('网络运营概览')}}</h2><p>{{simple?t('关注用量、成员与业务节点'):t('流量、用户与两类出口，一处掌握')}}</p></div><div class="dash-heading-actions"><span class="dash-updated"><i class="dot"/>{{date(data?.generated_at)}}</span><button :disabled="loading" @click="load();emit('refresh')"><RefreshCw :size="14" :class="{spin:loading}"/>{{t('刷新数据')}}</button></div></header>
 <div v-if="noLogs" class="dash-runtime-notice" role="status"><ShieldCheck :size="18"/><div><strong>{{t(state.runtime?.mode==='no_logs'?'无日志模式':'日志记录已暂停')}}</strong><p>{{t('流量趋势、操作审计与订阅访问时间已停止新增记录。历史空白不代表零用量，配额累计继续更新。')}}</p></div><button v-if="owner" class="text-button" @click="emit('navigate','settings')">{{t('系统设置')}}<ArrowUpRight :size="14"/></button></div>
 <p v-if="error" class="error" role="alert">{{t(error)}} <button @click="load">{{t('重试')}}</button></p>
 <div class="dash-metrics">
  <article><div><span>{{t('今日传输')}}</span><span class="dash-icon mint"><Activity :size="19"/></span></div><strong>{{data&&!noLogs?bytes(data.traffic.today):'—'}}</strong><small>{{t('累计传输')}} <b>{{bytes(state.totals.upload+state.totals.download)}}</b></small></article>
  <article><div><span>{{selectedLabel}} · {{noLogs?t('已保存区间流量'):t('区间流量')}}</span><span class="dash-icon blue"><CalendarDays :size="19"/></span></div><strong>{{data&&(!noLogs||total)?bytes(total):'—'}}</strong><small>{{comparison}}</small></article>
  <article><div><span>{{t('可用成员')}}</span><span class="dash-icon violet"><Users :size="19"/></span></div><strong>{{state.totals.active}}<em>/ {{state.users.length}}</em></strong><small>{{expiring}} {{t('位用户将在 7 天内到期')}}</small></article>
  <article><div><span>{{simple?t('启用普通节点'):t('启用接入节点')}}</span><span class="dash-icon amber"><RadioTower :size="19"/></span></div><strong>{{(simple?ordinary:state.nodes).filter(n=>n.enabled).length}}</strong><small v-if="simple">{{t('从普通订阅分发给已授权成员')}}</small><small v-else>{{t('普通')}} <b>{{ordinary.filter(n=>n.enabled).length}}</b><span>·</span>{{t('公共')}} <b>{{publicNodes.filter(n=>n.enabled).length}}</b></small></article>
 </div>
 <div class="dash-main-grid">
  <article class="dash-card dash-trends" :aria-busy="loading"><header><div><h3>{{noLogs?t('历史流量趋势'):t('流量趋势')}}</h3><p>{{noLogs?t('仅展示已保存记录；未记录的时段不代表没有使用。'):t('基于实际传输记录，按小时或日期汇总')}}</p></div><div class="dash-segments" :aria-label="t('流量时间范围')"><button v-for="p in periods" :key="p.id" :class="{selected:period===p.id}" :aria-pressed="period===p.id" @click="period=p.id">{{p.label}}</button></div></header>
   <div class="dash-chart-summary"><strong>{{noLogs&&!total?'—':bytes(total)}}</strong><div v-if="!noLogs||total" class="dash-legend"><button :aria-pressed="showDown" :class="{off:!showDown}" @click="showDown=!showDown"><i class="blue"/>{{t('下载')}} {{bytes(data?.traffic.download)}}</button><button :aria-pressed="showUp" :class="{off:!showUp}" @click="showUp=!showUp"><i class="mint"/>{{t('上传')}} {{bytes(data?.traffic.upload)}}</button></div></div>
   <div class="dash-chart" :aria-label="t('流量趋势图')" role="group"><span class="dash-scale">{{bytes(maxValue)}}</span><svg viewBox="0 0 720 180" preserveAspectRatio="none" aria-hidden="true"><defs><linearGradient id="dash-down" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#6d8cf5" stop-opacity=".23"/><stop offset="100%" stop-color="#6d8cf5" stop-opacity=".01"/></linearGradient><linearGradient id="dash-up" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#14b8a6" stop-opacity=".2"/><stop offset="100%" stop-color="#14b8a6" stop-opacity=".01"/></linearGradient></defs><line v-for="y in [20,60,100,140,179]" :key="y" x1="0" x2="720" :y1="y" :y2="y" class="dash-gridline"/><template v-if="buckets.length"><path v-if="showDown" :d="area('download')" fill="url(#dash-down)"/><path v-if="showUp" :d="area('upload')" fill="url(#dash-up)"/><path v-if="showDown" :d="path('download')" fill="none" stroke="#6d8cf5" stroke-width="2.5" vector-effect="non-scaling-stroke"/><path v-if="showUp" :d="path('upload')" fill="none" stroke="#14b8a6" stroke-width="2.5" vector-effect="non-scaling-stroke"/></template></svg>
    <div class="dash-chart-targets"><button v-for="(b,i) in buckets" :key="b.at" :aria-label="pointDate(b.at)+' '+t('下载')+' '+bytes(b.download)+' '+t('上传')+' '+bytes(b.upload)" @mouseenter="activePoint=i" @focus="activePoint=i" @mouseleave="activePoint=null" @blur="activePoint=null" @click="activePoint=i"/></div>
    <div v-if="inspected" class="dash-tooltip"><b>{{pointDate(inspected.at)}}</b><span>↓ {{bytes(inspected.download)}} · ↑ {{bytes(inspected.upload)}}</span></div><span v-if="!total&&!loading" class="dash-chart-empty">{{noLogs?t('此区间没有已保存的流量记录'):t('所选区间暂无流量')}}</span>
   </div><div class="dash-chart-labels"><span v-for="at in labels" :key="at">{{pointDate(at)}}</span></div>
   <details v-if="!simple&&(!noLogs||total>0)" class="dash-data"><summary>{{t('查看流量明细')}}</summary><div><table><thead><tr><th>{{t('时间')}}</th><th>{{t('上传')}}</th><th>{{t('下载')}}</th></tr></thead><tbody><tr v-for="b in buckets" :key="b.at"><td>{{pointDate(b.at)}}</td><td>{{bytes(b.upload)}}</td><td>{{bytes(b.download)}}</td></tr></tbody></table></div></details><p class="dash-history-note">{{t('最早流量记录')}} · {{date(data?.traffic.first_record)}} · {{t('保留最近 30 天')}}</p>
  </article>
  <article v-if="!simple" class="dash-card dash-health"><header><h3><Server :size="16"/>{{t('服务健康')}}</h3><span :class="['badge',state.system.status==='applied'?'success':'danger']">{{state.system.status==='applied'?t('已同步'):t('待处理')}}</span></header><div v-for="service in state.system.services||[]" :key="service.name" class="dash-service"><span>{{service.name}}</span><span><i :class="['dot',{warning:!service.active}]"/>{{service.active?t('运行中'):t('未运行')}}</span></div><dl><div><dt>{{t('控制台运行时间')}}</dt><dd>{{Math.floor(state.system.uptime/3600)}} h {{Math.floor(state.system.uptime/60)%60}} m</dd></div><div><dt>{{t('控制程序堆内存')}}</dt><dd>{{bytes(state.system.heap)}}</dd></div><div><dt>{{t('证书剩余')}}</dt><dd :class="{attention:certDays<14}">{{state.system.cert_expires?certDays:'—'}} {{t('天')}}</dd></div></dl><button v-if="owner" class="dash-card-link" @click="emit('navigate','system')">{{t('查看运维状态')}}<ArrowUpRight :size="14"/></button><div class="dash-shared-port"><ShieldCheck :size="16"/><span>{{t('统一公网入口')}}<b>TCP / UDP 443</b></span></div></article>
 </div>
 <div v-if="owner" class="dash-resource-grid">
  <article class="dash-card dash-business"><header><div class="dash-card-title"><span class="dash-icon mint"><Database :size="19"/></span><div><h3>{{t('业务资源')}}</h3><p>{{t('自有出口与上游订阅')}}</p></div></div><button class="icon" :aria-label="t('打开私有 IP 池')" @click="emit('navigate','ips')"><ArrowUpRight :size="17"/></button></header><div class="dash-resource-stats"><button @click="emit('navigate','ips')"><strong>{{healthy}}<em>/ {{privateIPs.length}}</em></strong><span>{{t('可用私有出口')}}</span></button><button @click="emit('navigate','nodes')"><strong>{{ordinary.length}}</strong><span>{{t('普通节点')}}</span></button><button @click="emit('navigate','sources')"><strong>{{data?.subscriptions?.total??'—'}}</strong><span>{{t('订阅来源')}}</span></button></div><div class="dash-task"><Clock3 :size="14"/><div><b>{{t('订阅每日错峰更新')}}</b><span>{{t('下次计划')}} · {{date(data?.subscriptions?.next_at)}}</span></div><span :class="['badge',data?.subscriptions?.failed?'danger':'neutral']">{{data?.subscriptions?.failed?t('有更新异常'):t('自动维护')}}</span></div><footer><button @click="emit('navigate','sources')"><Download :size="14"/>{{t('管理上游订阅')}}</button><button @click="emit('navigate','subscription')">{{t('普通订阅')}}<ArrowUpRight :size="14"/></button></footer></article>
  <article v-if="!simple" class="dash-card dash-public"><header><div class="dash-card-title"><span class="dash-icon blue"><Globe2 :size="19"/></span><div><h3>{{t('公共代理')}}</h3><p>{{t('独立采集、筛选与订阅')}}</p></div></div><span :class="['badge',data?.public?.enabled?'success':'neutral']">{{data?.public?.running?t('正在筛选'):data?.public?.enabled?t('采集已开启'):t('采集已关闭')}}</span></header><div class="dash-resource-stats"><button @click="emit('navigate','public')"><strong>{{publicIPs.length}}<em>/ {{data?.public?.max_resources??'—'}}</em></strong><span>{{t('可用公共出口')}}</span></button><button @click="emit('navigate','public-nodes')"><strong>{{publicNodes.length}}</strong><span>{{t('公共节点')}}</span></button><button @click="emit('navigate','public')"><strong>{{data?.public?.blacklist??'—'}}</strong><span>{{t('黑名单跳过资源')}}</span></button></div><div class="dash-task"><Zap :size="14"/><div><b>{{t('来源抓取与性能筛选')}}</b><span>{{data?.public?.enabled?t('下次计划')+' · '+date(data.public.next_at):t('来源可手动抓取，开启采集后检测入池')}}</span></div><span class="badge neutral">{{data?.public?.sources.filter(s=>s.queued||s.running).length||0}} {{t('项排队')}}</span></div><footer><button @click="emit('navigate','public/sources')"><Download :size="14"/>{{t('抓取公开来源')}}</button><button @click="emit('navigate','public-subscription')">{{t('公共订阅')}}<ArrowUpRight :size="14"/></button></footer></article>
 </div>
 <div class="dash-detail-grid">
  <article class="dash-card"><header><div><h3>{{t('用户用量排行')}}</h3><p>{{selectedLabel}} · {{noLogs?t('按已保存的区间记录排序'):t('按区间实际流量排序')}}</p></div><button v-if="owner" class="text-button" @click="emit('navigate','users')">{{t('用户管理')}}<ArrowUpRight :size="14"/></button></header><div v-for="(u,i) in data?.traffic.leaders||[]" :key="u.user_id" class="dash-leader"><span class="dash-rank">{{i+1}}</span><span class="avatar small">{{u.username.slice(0,1).toUpperCase()}}</span><div><strong>{{u.username}}</strong><div class="dash-meter"><i :style="{width:Math.max(2,(u.upload+u.download)/Math.max(1,total)*100)+'%'}"/></div></div><b>{{bytes(u.upload+u.download)}}</b></div><p v-if="!data?.traffic.leaders.length" class="dash-empty">{{noLogs?t('此区间没有已保存的流量记录'):t('所选区间暂无流量')}}</p><div v-if="!simple" class="dash-protocols"><span>{{t('协议累计占比')}}</span><div class="dash-protocol-bar"><i v-for="p in protocolTotals" :key="p.name" :style="{width:protocolTotal?p.value/protocolTotal*100+'%':'0%',background:p.color}"/></div><div><span v-for="p in protocolTotals" :key="p.name"><i :style="{background:p.color}"/>{{p.name}} <b>{{bytes(p.value)}}</b></span></div></div></article>
  <article v-if="owner" class="dash-card dash-attention"><header><h3><TriangleAlert :size="16"/>{{t('待处理事项')}}</h3><span class="count">{{attention.reduce((s,a)=>s+a.count,0)}}</span></header><button v-for="a in attention" :key="a.page+a.label" class="dash-attention-row" @click="emit('navigate',a.page)"><span>{{a.label}}</span><b>{{a.count}}</b><ArrowUpRight :size="14"/></button><div v-if="!attention.length" class="dash-all-clear"><CheckCircle2 :size="30"/><strong>{{t('暂无待处理事项')}}</strong><span>{{t('当前检测和账户状态未发现待处理提醒')}}</span></div><button v-if="!simple" class="dash-card-link" @click="emit('navigate','messages')">{{t('站内信')}} <span>{{state.unread_messages}} {{t('未读')}}</span><ArrowUpRight :size="14"/></button></article>
 </div>
 <div class="dash-detail-grid dash-region-grid">
  <article class="dash-card"><header><h3>{{simple?t('普通节点出口地区'):t('出口地区概览')}}</h3><span class="badge neutral">{{exits.length}} {{t('个独立出口')}}</span></header><div class="dash-exits"><div v-for="n in exits" :key="n.probe_ip"><CountryMark :code="n.country_code" :country="n.country"/><span><strong>{{n.country||t('国家待识别')}}</strong><small>{{n.probe_ip}}</small></span><i :class="['dot',{warning:!!n.probe_error}]"/></div></div><p v-if="!exits.length" class="dash-empty">{{t('等待出口检测')}}</p></article>
  <article v-if="owner&&!simple" class="dash-card"><header><h3>{{t('最近操作')}}</h3><button class="text-button" @click="emit('navigate','system')">{{t('查看全部')}}<ArrowUpRight :size="14"/></button></header><div v-for="(event,i) in state.audit.slice(0,5)" :key="event.at+':'+i" class="dash-audit"><i/><div><strong>{{auditName(event.action)}}</strong><small>{{event.actor}} · {{date(event.at)}}</small></div></div><p v-if="!state.audit.length" class="dash-empty">{{t('暂无操作记录')}}</p></article>
 </div>
</section>
</template>

<style scoped>
